export const photos: Record<string, Photo> = Object.fromEntries(
  Object.entries(data).map(([id, d]) => [id, { id, ...d, ...meta[id as keyof typeof data] }]),
);

export const getPhoto = (id?: string | null) => (id ? photos[id] : undefined);

